const apiData = await browserjs(tabId, async () => {
  // Let's find client_id from soundcloud scripts or fetch
  // In SoundCloud page, window.__sc_hydration or scripts usually have client_id, or we can check window
  let clientId = null;
  const scripts = Array.from(document.querySelectorAll('script[src]'));
  for (const s of scripts) {
    if (s.src.includes('client_id=')) {
      clientId = s.src.split('client_id=')[1].split('&')[0];
      break;
    }
  }

  // Let's also check if we can inspect any chart API endpoint
  // Or check window.__sc_hydration
  let hydration = null;
  if (window.__sc_hydration) {
    hydration = window.__sc_hydration;
  }

  return { clientId, hydrationCount: hydration ? hydration.length : null };
});

