  const urls = [
    "https://soundcloud.com/music-charts-us/sets/rock",
    "https://soundcloud.com/music-charts-uk/sets/rock"
  ];
  const out = [];
  for (const u of urls) {
    try {
      const resp = await fetch(u);
      out.push({ url: u, status: resp.status });
    } catch (e) {
      out.push({ url: u, error: e.message });
    }
  }
  return out;
});

