const profileInfo = await browserjs(tabId, async (clientId) => {
  const resp = await fetch(`https://api-v2.soundcloud.com/users/soundcloud:users:683411130?client_id=${clientId}`);
  // or resolve music-charts-us
  const respResolve = await fetch(`https://api-v2.soundcloud.com/resolve?url=https://soundcloud.com/music-charts-us&client_id=${clientId}`);
  const user = await respResolve.json();

  // also let's check charts API
  const chartsResp = await fetch(`https://api-v2.soundcloud.com/charts?kind=top&genre=soundcloud%3Agenres%3Arock&client_id=${clientId}&limit=10`);
  const charts = chartsResp.ok ? await chartsResp.json() : { status: chartsResp.status, text: await chartsResp.text() };

  return { user: { username: user.username, permalink: user.permalink, verified: user.verified, description: user.description }, charts };
}, clientInfo.id);

console.log("Profile & Charts API response:", JSON.stringify(profileInfo, null, 2));

